#ifndef DMG_DATA_H
#define DMG_DATA_H
#include <stdint.h>
/* generated by tools/gen_dmg_assets.py - do not edit.  DMG (4 shades) screen/HUD/sprite data of the one GB ROM
 * (main_gbc.c uses it when _cpu != CGB_TYPE).  Shares with src/gbc/gbc_data.h: GBC_BG_W/H, GBC_ELEV_TX, gbc_elev_ty,
 * GBC_HUD_NTILES and the GBC_HT_* ids (asserted equal by the generator).
 * Banked arrays: SWITCH_ROM(dmg_bank[s]) first.  Tile ids in the maps are final (HUD ids 0..60, screen tiles from DMG_TILE_BASE). */
#define DMG_FIRST_BANK 3u     /* = GBC_ROM_BANKS when generated (build_gbc.ps1 checks it) */
#define DMG_ROM_BANKS 5u      /* banks 0..4 used */
#define DMG_SRC_FINGERPRINT "183907c7b19c3fb9"  /* sha1 of src/spr_data.c (build_gbc.ps1 checks it) */
#define DMG_TILE_BASE 61u     /* first BG id of a screen's tiles */
#define DMG_BGP 228u
#define DMG_OBP0 224u               /* sprites: idx 1 white, idx 2 dark grey, idx 3 black */
#define DMG_OBP1 228u
extern const uint8_t dmg_bank[8];
extern const uint8_t dmg_ntiles[8];
extern const uint8_t *const dmg_chr[8];
extern const uint8_t *const dmg_map[8];
/* escalators (screens 0, 7): count, then per run tx, ty, w, and per phase 0..3: w tile ids */
extern const uint8_t *const dmg_esc[8];        /* 0 = none */
extern const uint8_t dmg_elev[];               /* [floor][state 0 closed,1 moving,2 open][4 ids] (bank dmg_bank[4]) */
#define DMG_HUD_BANK 3u
#define DMG_MARK_TILE_A 0x7Du             /* OBJ ids: Kop marker (white 2x2) */
#define DMG_MARK_TILE_B 0x7Eu             /* thief marker (black 2x2) */
#define DMG_MARK_TILE_C 0x7Fu             /* car marker (black 4x2 bar) */
extern const uint8_t dmg_hud_chr[];      /* bank DMG_HUD_BANK, GBC_HUD_NTILES tiles */
extern const uint8_t dmg_spr_chr[656];  /* bank DMG_HUD_BANK: spr_data.c tiles baked to OBP0 idx */
extern const uint8_t dmg_marker_chr[48];
extern const uint8_t dmg_chr_0[], dmg_map_0[];
extern const uint8_t dmg_chr_1[], dmg_map_1[];
extern const uint8_t dmg_chr_2[], dmg_map_2[];
extern const uint8_t dmg_chr_3[], dmg_map_3[];
extern const uint8_t dmg_chr_4[], dmg_map_4[];
extern const uint8_t dmg_chr_5[], dmg_map_5[];
extern const uint8_t dmg_chr_6[], dmg_map_6[];
extern const uint8_t dmg_chr_7[], dmg_map_7[];
extern const uint8_t dmg_esc_0[];
extern const uint8_t dmg_esc_7[];
#endif
